package com.lifeflow;

import java.time.*;
import java.util.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.CommandLineRunner;
import org.springframework.context.annotation.Bean;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.web.bind.annotation.*;
import jakarta.servlet.http.HttpSession;

@RestController @RequestMapping("/api") public class Api {
 @Autowired JdbcTemplate db;
 BCryptPasswordEncoder encoder=new BCryptPasswordEncoder();
 static final List<String> GROUPS=List.of("A+","A-","B+","B-","AB+","AB-","O+","O-");
 static final List<String> COMPONENTS=List.of("Whole Blood","Packed Red Cells","Platelets","Plasma");
 @Bean CommandLineRunner seed(JdbcTemplate db){return args->{
  if(db.queryForObject("select count(*) from banks",Integer.class)==0){String[][] banks={{"Lifeline Community Blood Centre","Vijayawada","Benz Circle, Vijayawada"},{"HopeCare Blood Centre","Guntur","Brodipet, Guntur"},{"Sanjeevani Blood Centre","Mangalagiri","Main Road, Mangalagiri"},{"Coastal Care Blood Centre","Visakhapatnam","MVP Colony, Visakhapatnam"},{"RedLeaf Blood Centre","Tirupati","Renigunta Road, Tirupati"},{"CityCare Blood Centre","Vijayawada","Governorpet, Vijayawada"}};
  for(String[] b:banks)db.update("insert into banks(name,city,address,phone) values(?,?,?,?)",b[0],b[1],b[2],"0000000000");
  for(int i=1;i<=banks.length;i++)for(int j=0;j<GROUPS.size();j++)for(int k=0;k<COMPONENTS.size();k++)db.update("insert into inventory(bank_id,blood_group,component,units) values(?,?,?,?)",i,GROUPS.get(j),COMPONENTS.get(k),(i*7+j*3+k*5)%28);
  }
  if(db.queryForObject("select count(*) from camps",Integer.class)==0){db.update("insert into camps(name,city,venue,event_date,organizer) values('Give Hope Blood Drive','Vijayawada','Community Wellness Hall',DATEADD('DAY',14,CURRENT_DATE),'LifeFlow Volunteers'),('Campus Kindness Camp','Mangalagiri','University Community Centre',DATEADD('DAY',21,CURRENT_DATE),'Youth Care Collective'),('Together We Give','Guntur','City Community Auditorium',DATEADD('DAY',30,CURRENT_DATE),'HopeCare Volunteers')");}
  if(db.queryForObject("select count(*) from users where role='ADMIN'",Integer.class)==0)db.update("insert into users(name,email,password,city,blood_group,role) values(?,?,?,?,?,?)","Demo Administrator","admin@lifeflow.demo",encoder.encode("DemoAdmin@123"),"Vijayawada","O+","ADMIN");
 };}
 Map<String,Object> user(HttpSession s){Object id=s.getAttribute("uid");if(id==null)throw new ApiError(HttpStatus.UNAUTHORIZED,"Please log in first");return db.queryForMap("select id,name,email,phone,city,blood_group,role from users where id=?",id);}
 void admin(HttpSession s){if(!"ADMIN".equals(user(s).get("ROLE")))throw new ApiError(HttpStatus.FORBIDDEN,"Administrator access required");}
 String str(Map<String,Object> m,String key){return Objects.toString(m.get(key),"").trim();}
 void require(boolean b,String msg){if(!b)throw new ApiError(HttpStatus.BAD_REQUEST,msg);}
 @GetMapping("/health") Map<String,String> health(){return Map.of("status","ok");}
 @GetMapping("/banks") Object banks(){return db.queryForList("select * from banks order by city,name");}
 @GetMapping("/inventory") Object inventory(@RequestParam(defaultValue="") String city,@RequestParam(defaultValue="") String group,@RequestParam(defaultValue="") String component){return db.queryForList("select i.id,b.name bank,b.city,b.address,b.phone,i.bank_id,i.blood_group,i.component,i.units,i.updated_at from inventory i join banks b on b.id=i.bank_id where lower(b.city) like ? and i.blood_group like ? and i.component like ? order by b.city,b.name", "%"+city.toLowerCase()+"%",group.isEmpty()?"%":group,component.isEmpty()?"%":component);}
 @GetMapping("/camps") Object camps(){return db.queryForList("select * from camps where event_date>=CURRENT_DATE order by event_date");}
 @PostMapping("/register") Object register(@RequestBody Map<String,Object> m,HttpSession s){String name=str(m,"name"),email=str(m,"email").toLowerCase(),pass=str(m,"password"),group=str(m,"bloodGroup");require(name.length()>=2&&name.length()<=100,"Enter a valid name");require(email.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$"),"Enter a valid email");require(pass.length()>=8,"Password must be at least 8 characters");require(GROUPS.contains(group),"Select a blood group");try{db.update("insert into users(name,email,password,phone,city,blood_group,role) values(?,?,?,?,?,?,'DONOR')",name,email,encoder.encode(pass),str(m,"phone"),str(m,"city"),group);}catch(DataIntegrityViolationException e){throw new ApiError(HttpStatus.CONFLICT,"This email is already registered");}Long id=db.queryForObject("select id from users where email=?",Long.class,email);s.setAttribute("uid",id);return user(s);}
 @PostMapping("/login") Object login(@RequestBody Map<String,Object> m,HttpSession s){List<Map<String,Object>> found=db.queryForList("select id,password from users where email=?",str(m,"email").toLowerCase());if(found.isEmpty()||!encoder.matches(str(m,"password"),String.valueOf(found.get(0).get("PASSWORD"))))throw new ApiError(HttpStatus.UNAUTHORIZED,"Incorrect email or password");s.setAttribute("uid",found.get(0).get("ID"));return user(s);}
 @GetMapping("/me") Object me(HttpSession s){return user(s);}
 @PostMapping("/logout") Object logout(HttpSession s){s.invalidate();return Map.of("message","Signed out");}
 @PostMapping("/appointments") Object appointment(@RequestBody Map<String,Object> m,HttpSession s){Map<String,Object> u=user(s);long bank=Long.parseLong(str(m,"bankId"));LocalDate day=LocalDate.parse(str(m,"date"));String slot=str(m,"slot");require(day.isAfter(LocalDate.now())&&day.isBefore(LocalDate.now().plusMonths(4)),"Choose a future date within four months");require(List.of("09:00","10:00","11:00","14:00","15:00").contains(slot),"Choose a valid time slot");require(db.queryForObject("select count(*) from banks where id=?",Integer.class,bank)>0,"Invalid blood centre");int count=db.queryForObject("select count(*) from appointments where bank_id=? and visit_date=? and slot=? and status='CONFIRMED'",Integer.class,bank,day,slot);require(count<5,"This time slot is fully booked");db.update("insert into appointments(user_id,bank_id,visit_date,slot) values(?,?,?,?)",u.get("ID"),bank,day,slot);return Map.of("message","Appointment confirmed");}
 @GetMapping("/appointments") Object appointments(HttpSession s){return db.queryForList("select a.id,a.visit_date,a.slot,a.status,b.name bank,b.city from appointments a join banks b on b.id=a.bank_id where a.user_id=? order by a.visit_date desc",user(s).get("ID"));}
 @PostMapping("/appointments/{id}/cancel") Object cancel(@PathVariable long id,HttpSession s){int n=db.update("update appointments set status='CANCELLED' where id=? and user_id=? and status='CONFIRMED'",id,user(s).get("ID"));require(n>0,"Appointment not found or already cancelled");return Map.of("message","Appointment cancelled");}
 @PostMapping("/requests") Object request(@RequestBody Map<String,Object> m,HttpSession s){Map<String,Object> u=user(s);String patient=str(m,"patient"),group=str(m,"bloodGroup"),component=str(m,"component");int units;try{units=Integer.parseInt(str(m,"units"));}catch(Exception e){throw new ApiError(HttpStatus.BAD_REQUEST,"Invalid units");}require(patient.length()>=2&&GROUPS.contains(group)&&COMPONENTS.contains(component)&&units>0&&units<=20,"Check patient, group, component and units");String hospital=str(m,"hospital"),city=str(m,"city"),phone=str(m,"phone");require(!hospital.isBlank()&&!city.isBlank()&&phone.matches("[0-9+ -]{10,16}"),"Enter hospital, city and a valid phone number");LocalDate day=LocalDate.parse(str(m,"date"));require(!day.isBefore(LocalDate.now()),"Date cannot be in the past");db.update("insert into requests(user_id,patient,blood_group,component,units,hospital,city,phone,needed) values(?,?,?,?,?,?,?,?,?)",u.get("ID"),patient,group,component,units,hospital,city,phone,day);return Map.of("message","Request submitted for demo review; blood is not reserved");}
 @GetMapping("/requests") Object requests(HttpSession s){return db.queryForList("select * from requests where user_id=? order by created_at desc",user(s).get("ID"));}
 @PostMapping("/camps/{id}/join") Object join(@PathVariable long id,HttpSession s){require(db.queryForObject("select count(*) from camps where id=? and event_date>=CURRENT_DATE",Integer.class,id)>0,"Camp not available");try{db.update("insert into camp_signups(user_id,camp_id) values(?,?)",user(s).get("ID"),id);}catch(DataIntegrityViolationException e){throw new ApiError(HttpStatus.CONFLICT,"Already registered for this camp");}return Map.of("message","Camp registration successful");}
 @GetMapping("/my-camps") Object myCamps(HttpSession s){return db.queryForList("select c.* from camps c join camp_signups s on s.camp_id=c.id where s.user_id=?",user(s).get("ID"));}
 @GetMapping("/admin/requests") Object adminRequests(HttpSession s){admin(s);return db.queryForList("select r.*,u.name requester from requests r join users u on u.id=r.user_id order by r.created_at desc");}
 @PostMapping("/admin/requests/{id}/status") Object status(@PathVariable long id,@RequestBody Map<String,Object> m,HttpSession s){admin(s);String status=str(m,"status");require(List.of("PENDING","APPROVED","REJECTED","FULFILLED").contains(status),"Invalid status");require(db.update("update requests set status=? where id=?",status,id)>0,"Request not found");return Map.of("message","Request updated");}
 @PostMapping("/admin/inventory/{id}") Object stock(@PathVariable long id,@RequestBody Map<String,Object> m,HttpSession s){admin(s);int units;try{units=Integer.parseInt(str(m,"units"));}catch(Exception e){throw new ApiError(HttpStatus.BAD_REQUEST,"Invalid stock value");}require(units>=0&&units<=10000,"Stock must be between 0 and 10000");require(db.update("update inventory set units=?,updated_at=CURRENT_TIMESTAMP where id=?",units,id)>0,"Inventory record not found");return Map.of("message","Demo inventory updated");}
 @GetMapping("/admin/stats") Object stats(HttpSession s){admin(s);return Map.of("donors",db.queryForObject("select count(*) from users where role='DONOR'",Integer.class),"banks",db.queryForObject("select count(*) from banks",Integer.class),"requests",db.queryForObject("select count(*) from requests",Integer.class),"appointments",db.queryForObject("select count(*) from appointments",Integer.class));}
 @ExceptionHandler(ApiError.class) ResponseEntity<?> apiError(ApiError e){return ResponseEntity.status(e.status).body(Map.of("error",e.getMessage()));}
 @ExceptionHandler({IllegalArgumentException.class,java.time.format.DateTimeParseException.class}) ResponseEntity<?> bad(Exception e){return ResponseEntity.badRequest().body(Map.of("error","Invalid input. Please check your form."));}
 static class ApiError extends RuntimeException{final HttpStatus status;ApiError(HttpStatus status,String message){super(message);this.status=status;}}
}
